input.contents:
/**
 * 结算面：
 * - path 态（第一步）：只亮本问 pathKey + 各 path 绑定的 bookKey；确认 / 撤销
 * - 复用线：norm 提案 → 批准 / 撤销→新铸（仍保留批闸）
 */

import { useEffect, useMemo, useState } from 'react'
import { useAttentionIo } from '../reasoning/attentionIoStore'
import { useIndexGate } from '../reasoning/indexGate'
import { useDocuverse } from '../canvas/store'
import {
  exitSettlementFrame,
} from '../canvas/settleFrame'
import { formatDirectedPathIncrementReturn } from '../arch/pathIncrementReturn'
import { runAutoFlow } from '../reasoning/autoFlow'
import { newLlmCallId } from '../reasoning/settleMint'

function short(k: string, n = 10): string {
  const t = k.trim()
  if (t.length <= n) return t
  return `${t.slice(0, 4)}…${t.slice(-4)}`
}

export function SettlementDeskPanel() {
  const pendingReuse = useAttentionIo((s) => s.pendingReuseProposal)
  const pendingPath = useAttentionIo((s) => s.pendingPathMatch)
  const bookIndex = useIndexGate((s) => s.bookIndex)
  const [busy, setBusy] = useState(false)
  const [selectedNorms, setSelectedNorms] = useState<Set<string>>(new Set())
  const [selectedPaths, setSelectedPaths] = useState<Set<string>>(new Set())
  const [status, setStatus] = useState<string | null>(null)

  const mode: 'reuse' | 'path' | null = pendingReuse
    ? 'reuse'
    : pendingPath
      ? 'path'
      : null

  const pathRows = useMemo(() => {
    if (!pendingPath) return [] as Array<{
      pathKey: string
      bookKeys: string[]
    }>
    const pairs = pendingPath.boundPairs ?? []
    if (pairs.length > 0) {
      return pairs.map((p) => ({
        pathKey: p.pathKey,
        bookKeys: [...new Set(p.sharedBookKeys.filter(Boolean))],
      }))
    }
    return (pendingPath.pathKeys ?? []).map((pathKey) => ({
      pathKey,
      bookKeys: [] as string[],
    }))
  }, [pendingPath])

  const reuseBookKeys = useMemo(() => {
    if (!pendingReuse) return [] as string[]
    return [
      ...new Set(pendingReuse.candidates.flatMap((c) => c.bookKeys)),
    ].filter(Boolean)
  }, [pendingReuse])

  useEffect(() => {
    if (!mode) {
      exitSettlementFrame()
      setStatus(null)
      return
    }
    if (pendingReuse) {
      setSelectedNorms(new Set(pendingReuse.candidates.map((c) => c.normKey)))
    }
    if (pendingPath) {
      setSelectedPaths(new Set(pathRows.map((r) => r.pathKey)))
    }
    // path 第一步：不自动开球 / 不进结算架；只等人确认或撤销
  }, [
    mode,
    pendingReuse?.createdAt,
    pendingPath?.createdAt,
    pathRows.map((r) => r.pathKey).join('|'),
  ])

  if (!mode) return null

  const onApproveReuse = () => {
    if (busy) return
    setBusy(true)
    try {
      const res = useAttentionIo.getState().approvePendingReuse({
        normKeys: [...selectedNorms],
        llmCallId: newLlmCallId('reuse'),
      })
      setStatus(res.note)
      if (res.ok) {
        const pathReturn = formatDirectedPathIncrementReturn({
          question: pendingReuse!.question,
          hopOutputs: [],
          mode: 'reuse',
          queryKey: pendingReuse!.queryKey,
        })
        useAttentionIo.getState().setDeskPrompt(
          `复用已批准 · ${res.note}`,
        )
        useAttentionIo.getState().setLastStatus(pathReturn.slice(0, 200))
        exitSettlementFrame()
      }
    } finally {
      setBusy(false)
    }
  }

  const onRejectReuse = async () => {
    if (busy || !bookIndex) return
    setBusy(true)
    try {
      const r = useAttentionIo.getState().rejectPendingReuse()
      if (!r) return
      exitSettlementFrame()
      setStatus('已撤销复用 · 续跑新铸…')
      const sealItems = (
        items: Array<{
          key: string
          brief: string
          briefKey: string
          bookText?: string
        }>,
      ) => {
        const sealAttentionBond = useDocuverse.getState().sealAttentionBond
        return items.map((it) => {
          const chunk = bookIndex.chunks.find((c) => c.key === it.key)
          const bbox = chunk
            ? ([...chunk.bbox] as [number, number, number, number])
            : ([0, 0, 100, 100] as [number, number, number, number])
          const bondId = sealAttentionBond({
            strandIndex: chunk?.page ?? 0,
            bbox,
            confirmedText: it.bookText || it.key,
            comment: it.brief,
            bookKey: it.key,
            briefKey: it.briefKey,
          })
          return { ...it, bondId }
        })
      }
      const out = await runAutoFlow({
        question: r.question,
        bookIndex,
        skipReuse: true,
        excludeBriefKeys: r.excludeBriefKeys,
        sealItems,
        onProgress: (msg) => setStatus(msg),
      })
      useAttentionIo.getState().setDeskPrompt(out.note)
      setStatus(out.note)
    } finally {
      setBusy(false)
    }
  }

  const onConfirmPaths = () => {
    if (busy) return
    setBusy(true)
    try {
      const res = useAttentionIo.getState().settleUserPathMatches({
        queryKey: pendingPath?.queryKey,
        pathKeys: [...selectedPaths],
      })
      setStatus(res.note)
      if (res.ok) {
        useAttentionIo.getState().setLastStatus(res.note)
        exitSettlementFrame()
      }
    } finally {
      setBusy(false)
    }
  }

  const onRevokePaths = () => {
    if (busy) return
    setBusy(true)
    try {
      useAttentionIo.getState().clearPendingPathMatch()
      useAttentionIo.getState().setLastStatus('已撤销 path 候选 · 未登记 norm')
      setStatus('已撤销')
      exitSettlementFrame()
    } finally {
      setBusy(false)
    }
  }

  return (
    <aside
      className={
        mode === 'path'
          ? 'settlement-desk settlement-desk--path-only'
          : 'settlement-desk'
      }
      aria-label="结算面板"
    >
      <header className="settlement-desk-head">
        <span className="settlement-desk-title">
          {mode === 'reuse' ? '结算 · 复用闸' : '结算 · 确认 path'}
        </span>
        {status ? <span className="settlement-desk-status">{status}</span> : null}
      </header>

      {mode === 'path' && pendingPath ? (
        <div className="settlement-body">
          <div className="settlement-k">
            query <code title={pendingPath.queryKey}>{short(pendingPath.queryKey, 16)}</code>
            {pendingPath.question ? (
              <span className="settlement-q"> · {pendingPath.question.slice(0, 72)}
                {pendingPath.question.length > 72 ? '…' : ''}
              </span>
            ) : null}
          </div>
          <ul className="settlement-rows">
            {pathRows.map((row) => (
              <li key={row.pathKey} className="settlement-row">
                <label className="settlement-check">
                  <input
                    type="checkbox"
                    checked={selectedPaths.has(row.pathKey)}
                    onChange={() => {
                      setSelectedPaths((prev) => {
                        const n = new Set(prev)
                        if (n.has(row.pathKey)) n.delete(row.pathKey)
                        else n.add(row.pathKey)
                        return n
                      })
                    }}
                  />
                  <span>
                    pathKey <code title={row.pathKey}>{short(row.pathKey, 18)}</code>
                  </span>
                </label>
                <div className="settlement-book-list">
                  <div className="settlement-k">
                    bookKey×{row.bookKeys.length}
                  </div>
                  {row.bookKeys.length > 0 ? (
                    <ul>
                      {row.bookKeys.map((bk) => (
                        <li key={bk}>
                          <span className="settlement-chip settlement-chip--static" title={bk}>
                            {short(bk, 18)}
                          </span>
                        </li>
                      ))}
                    </ul>
                  ) : (
                    <p className="settlement-hint">无绑定 bookKey</p>
                  )}
                </div>
              </li>
            ))}
          </ul>
          <div className="settlement-actions">
            <button
              type="button"
              className="settlement-btn primary"
              disabled={busy || selectedPaths.size === 0}
              onClick={onConfirmPaths}
            >
              确认
            </button>
            <button
              type="button"
              className="settlement-btn danger"
              disabled={busy}
              onClick={onRevokePaths}
            >
              撤销
            </button>
          </div>
        </div>
      ) : null}

      {mode === 'reuse' && pendingReuse ? (
        <div className="settlement-body">
          {reuseBookKeys.length > 0 ? (
            <div className="settlement-book-list">
              <div className="settlement-k">材料 bookKey×{reuseBookKeys.length}</div>
              <ul>
                {reuseBookKeys.map((bk) => (
                  <li key={bk}>
                    <span className="settlement-chip settlement-chip--static" title={bk}>
                      {short(bk, 14)}
                    </span>
                  </li>
                ))}
              </ul>
            </div>
          ) : null}
          <div className="settlement-k">
            提案 normKey×{pendingReuse.candidates.length}
          </div>
          <ul className="settlement-rows">
            {pendingReuse.candidates.map((c) => (
              <li key={c.normKey} className="settlement-row">
                <label className="settlement-check">
                  <input
                    type="checkbox"
                    checked={selectedNorms.has(c.normKey)}
                    onChange={() => {
                      setSelectedNorms((prev) => {
                        const n = new Set(prev)
                        if (n.has(c.normKey)) n.delete(c.normKey)
                        else n.add(c.normKey)
                        return n
                      })
                    }}
                  />
                  <span>
                    norm <code>{short(c.normKey)}</code> · path{' '}
                    <code>{short(c.pathKey)}</code>
                  </span>
                </label>
              </li>
            ))}
          </ul>
          <div className="settlement-actions">
            <button
              type="button"
              className="settlement-btn primary"
              disabled={busy || selectedNorms.size === 0}
              onClick={onApproveReuse}
            >
              批准复用
            </button>
            <button
              type="button"
              className="settlement-btn danger"
              disabled={busy}
              onClick={() => void onRejectReuse()}
            >
              撤销 → 新铸
            </button>
          </div>
        </div>
      ) : null}
    </aside>
  )
}

import { CvsScene } from './canvas/CvsScene'
import { HUD } from './ui/HUD'
import { KeyboardNav } from './ui/KeyboardNav'
import { A1ChatDock } from './ui/A1ChatDock'
import { LlmIoStreamPanel } from './ui/LlmIoStreamPanel'
import { SettlementDeskPanel } from './ui/SettlementDeskPanel'
import { TocWizard } from './ui/TocWizard'
import { TocWizardBoundary } from './ui/TocWizardBoundary'
import { useDocuverse } from './canvas/store'
import { useAttentionIo } from './reasoning/attentionIoStore'
import './App.css'

/**
 * no-peek 实验壳：主界面 = LLM I/O 信息流 + 提问。
 * path/reuse 挂起时：只亮结算面（pathKey + 绑定 bookKey），收起 I/O 流与球壳。
 */
export default function App() {
  const letterWorkbench = useDocuverse((s) => s.letterWorkbenchMode)
  const sphereAudit = useDocuverse((s) => s.sphereAuditOpen)
  const indexReadyHint = useDocuverse((s) => s.uploadLabel)
  const pendingPath = useAttentionIo((s) => s.pendingPathMatch)
  const pendingReuse = useAttentionIo((s) => s.pendingReuseProposal)
  const settlementOpen = Boolean(pendingPath || pendingReuse)

  // 结算第一步：不亮球 / 不亮 I/O；其余实验壳照常
  const showSphere =
    !settlementOpen && (!letterWorkbench || sphereAudit)
  const showIoStream = !settlementOpen

  return (
    <div
      className={
        settlementOpen
          ? 'app-root app-root--io-lab app-root--settlement'
          : 'app-root app-root--io-lab'
      }
    >
      <KeyboardNav />
      <main
        className={
          settlementOpen
            ? 'stage stage--io-lab stage--settlement'
            : 'stage stage--io-lab'
        }
      >
        {showSphere ? (
          <CvsScene />
        ) : (
          <div className="letter-workbench-stage letter-workbench-stage--compact">
            <p className="letter-workbench-title">
              {settlementOpen ? '结算 · 等人确认' : 'no-peek · I/O 实验'}
            </p>
            <p className="letter-workbench-sub">
              {settlementOpen
                ? pendingPath
                  ? `本问 pathKey×${pendingPath.pathKeys?.length ?? 0} · 只亮 path 与绑定 bookKey`
                  : '复用提案待批'
                : indexReadyHint
                  ? `语料：${indexReadyHint}`
                  : '先上传 PDF；右侧看每次 LLM 的 system / user / output'}
            </p>
          </div>
        )}
        {showIoStream ? <LlmIoStreamPanel /> : null}
      </main>
      {!settlementOpen ? <HUD /> : null}
      <SettlementDeskPanel />
      {!settlementOpen ? <A1ChatDock /> : null}
      <TocWizardBoundary>
        <TocWizard />
      </TocWizardBoundary>
      <footer className="patent-bar">
        {settlementOpen
          ? '结算闸 · 确认 path / 撤销 · 5175'
          : '实验仓 · LLM I/O 信息流 · 一键复制可贴回 Cursor · 5175'}
      </footer>
    </div>
  )
}

