/**
 * 结算三栏上球：只物化一页，摆到 front slot，相机正对；保留 layout 框高亮。
 */
export async function focusSettlementAuditBook(input: {
  bookKey: string
  bookIndex: BookIndex
}): Promise<boolean> {
  const strand = pageOfBookKey(input.bookKey, input.bookIndex)
  if (strand == null) return false
  await useDocuverse.getState().ensurePageForAudit(strand, { focus: true })
  useDocuverse.getState().revealSphereForAudit()

  // 与 CvsScene settlementAudit 的 pageHomePosition(0,1) 对齐
  const home = pageHomePosition(0, 1)
  const radial = new THREE.Vector3(home[0], 0, home[2])
  if (radial.lengthSq() < 1e-6) radial.set(0, 0, 1)
  radial.normalize()
  const eyeDist = Math.max(innerSphereRadius(1) * 2.35, 6.5)
  const eyeV = radial.clone().multiplyScalar(eyeDist)
  eyeV.y = home[1] + 0.35
  const lookAt: [number, number, number] = [home[0], home[1], home[2]]
  const eye: [number, number, number] = [eyeV.x, eyeV.y, eyeV.z]
  const { yaw, pitch } = radialToYawPitch(eyeV)

  locked = {
    kind: 'path',
    eye,
    lookAt,
    yaw,
    pitch,
    distance: eyeV.length(),
    slotRingAngle: 0,
    activeBookKey: input.bookKey,
  }
  clearPokerYawOffset()
  useDocuverse.setState({ currentStrand: strand })
  applyCamera(locked)
  focusA1KeyOnPdf({
    key: input.bookKey,
    bookIndex: input.bookIndex,
    swoopToPage: () => {},
  })
  applyCamera(locked)
  return true
}

