                seen.add(bk)
                bookKeysSequence.push(bk)
              }
            }
            return {
              solutionKey: sk,
              conclusion:
                (edges[0]?.conclusion ?? '').trim() ||
                steps.map((s) => s.inferText).filter(Boolean).join('；'),
              pathIndex: edges[0]?.pathIndex ?? 0,
