/**
 * 结算架：infer 激活的物化页都留在球上；点 bookKey 跳转对焦该页。
 * 强调笔 / 微球面板在结算态仍可用。
 */

import * as THREE from 'three'
import type { BookIndex } from '../reasoning/pipelineA'
import { bookKeyHostWorld } from '../reasoning/keyWorldAnchor'
import { focusA1KeyOnPdf } from '../reasoning/focusA1Key'
import { useDocuverse } from './store'
import {
  clearPokerYawOffset,
  innerSphereRadius,
  pageHomePosition,
  radialToYawPitch,
} from './geometry'
import { singleAnchorShellPoint } from './surfaceGeometry'

export type SettlementKind = 'reuse' | 'path'

type LockedSettlementFrame = {
  kind: SettlementKind
  eye: [number, number, number]
  lookAt: [number, number, number]
  yaw: number
  pitch: number
  distance: number
  /** 保留字段；多页球模式下不再用 poker 转单槽 */
  slotRingAngle: number
  activeBookKey: string
}

let locked: LockedSettlementFrame | null = null

function pageOfBookKey(
  bookKey: string,
  bookIndex: BookIndex,
): number | null {
  const chunk = bookIndex.chunks.find((c) => c.key === bookKey)
  return chunk ? chunk.page : null
}

function applyCamera(frame: LockedSettlementFrame) {
  useDocuverse.setState({
    cameraLens: 'construction',
    constructionLinkId: null,
    keyComparePair: null,
    keyCompareTri: null,
    cameraEye: frame.eye,
    cameraLookAt: frame.lookAt,
    viewYaw: frame.yaw,
    viewPitch: frame.pitch,
    cameraDistance: frame.distance,
    viewPan: [0, 0, 0],
    constructionStage: 'rail',
    constructionDepth: 'commentNear',
    commentLayerExpanded: true,
    swooping: false,
    settlementSphereEpoch: useDocuverse.getState().settlementSphereEpoch + 1,
  })
}

/** 相机正对球壳上该 strand 的自然槽位（多页同球） */
function cameraFrameForStrand(
  strand: number,
  kind: SettlementKind,
  activeBookKey: string,
): LockedSettlementFrame {
  const total = Math.max(useDocuverse.getState().pages.length, 1)
  const home = pageHomePosition(strand, total)
  const radial = new THREE.Vector3(home[0], 0, home[2])
  if (radial.lengthSq() < 1e-6) radial.set(0, 0, 1)
  radial.normalize()
  const eyeDist = Math.max(innerSphereRadius(total) * 2.35, 6.5)
  const eyeV = radial.clone().multiplyScalar(eyeDist)
  eyeV.y = home[1] + 0.35
  const lookAt: [number, number, number] = [home[0], home[1], home[2]]
  const eye: [number, number, number] = [eyeV.x, eyeV.y, eyeV.z]
  const { yaw, pitch } = radialToYawPitch(eyeV)
  return {
    kind,
    eye,
    lookAt,
    yaw,
    pitch,
    distance: eyeV.length(),
    slotRingAngle: 0,
    activeBookKey,
  }
}

async function prepareAuditPage(
  bookKey: string,
  bookIndex: BookIndex,
  focus: boolean,
): Promise<number | null> {
  const strand = pageOfBookKey(bookKey, bookIndex)
  if (strand == null) return null
  await useDocuverse.getState().ensurePageForAudit(strand, { focus })
  useDocuverse.getState().revealSphereForAudit()
  return strand
}

/**
 * 进入结算球：物化对焦页，相机看向其自然槽；其它已物化页仍留在球上。
 */
export async function enterSettlementSingleAnchor(input: {
  kind: SettlementKind
  bookKey: string
  bookIndex: BookIndex
}): Promise<boolean> {
  const strand = await prepareAuditPage(input.bookKey, input.bookIndex, true)
  if (strand == null) return false

  clearPokerYawOffset()
  locked = cameraFrameForStrand(strand, input.kind, input.bookKey)
  useDocuverse.setState({ currentStrand: strand })
  applyCamera(locked)
  focusA1KeyOnPdf({
    key: input.bookKey,
    bookIndex: input.bookIndex,
    swoopToPage: () => {},
  })
  applyCamera(locked)
  return true
}

/**
 * 结算三栏上球：物化并跳到该 book 页槽；同球其它 infer 激活页保持可见。
 */
export async function focusSettlementAuditBook(input: {
  bookKey: string
  bookIndex: BookIndex
}): Promise<boolean> {
  const strand = await prepareAuditPage(input.bookKey, input.bookIndex, true)
  if (strand == null) return false

  clearPokerYawOffset()
  locked = cameraFrameForStrand(strand, 'path', input.bookKey)
  useDocuverse.setState({ currentStrand: strand })
  applyCamera(locked)
  focusA1KeyOnPdf({
    key: input.bookKey,
    bookIndex: input.bookIndex,
    swoopToPage: () => {},
  })
  applyCamera(locked)
  return true
}

/** 列表切 book：物化该页并跳到自然槽（不把整球收成单页） */
export async function settlementSelectBookKey(input: {
  bookKey: string
  bookIndex: BookIndex
}): Promise<boolean> {
  if (!locked) {
    return enterSettlementSingleAnchor({
      kind: 'path',
      bookKey: input.bookKey,
      bookIndex: input.bookIndex,
    })
  }
  return focusSettlementAuditBook(input)
}

export function getSettlementFrame(): LockedSettlementFrame | null {
  return locked
}

export function exitSettlementFrame(): void {
  locked = null
  clearPokerYawOffset()
  useDocuverse.getState().hideSphereAfterAudit()
  useDocuverse.setState({
    commentLayerExpanded: false,
    settlementSphereEpoch: useDocuverse.getState().settlementSphereEpoch + 1,
  })
}

/** @deprecated 保留导出以免旧引用断裂；多页球不再使用 host 单锚 */
export function _legacyHostUnused(
  bookKey: string,
  bookIndex: BookIndex,
): boolean {
  const pages = useDocuverse.getState().pages.length
  return Boolean(bookKeyHostWorld(bookKey, bookIndex, pages))
}

