/**
 * 由 queryKey 展开的增量 key 结构（只读台账，不调 LLM）。
 */

import { useAttentionIo } from './attentionIoStore'
import { listQueryChildren, listQueryAncestors } from '../arch/queryLineage'

export type QueryIncrementKind =
  | 'brief'
  | 'prospect'
  | 'infer'
  | 'solution'
  | 'path'
  | 'norm'
  | 'neighbour'
  | 'reuse'
  | 'book'

export type QueryIncrementNode = {
  kind: QueryIncrementKind
  key: string
  label: string
  parentKey?: string
  meta?: string
}

export type QueryIncrementTree = {
  queryKey: string
  question: string
  parentQueryKey: string | null
  childQueryKeys: string[]
  ancestorQueryKeys: string[]
  nodes: QueryIncrementNode[]
  /** bookKey 去重并集（infer + prospect） */
  bookKeys: string[]
}

export function listSettledQueryKeysNewestFirst(): Array<{
  queryKey: string
  question: string
}> {
  const settled = useAttentionIo.getState().settledQueries
  return Object.entries(settled)
    .map(([queryKey, question]) => ({ queryKey, question }))
    .reverse()
}

/** 点开某 queryKey → 它如何引出后续增量 key */
export function buildQueryIncrementTree(queryKey: string): QueryIncrementTree {
  const st = useAttentionIo.getState()
  const qk = queryKey.trim()
  const parentOf = st.queryParentOf
  const question = st.settledQueries[qk] ?? ''
  const parentQueryKey = parentOf[qk] ?? null
  const childQueryKeys = listQueryChildren(parentOf, qk)
  const ancestorQueryKeys = listQueryAncestors(parentOf, qk)

  const nodes: QueryIncrementNode[] = []
  const bookSet = new Set<string>()

  for (const bk of st.queryKeyToBriefKeys[qk] ?? []) {
    nodes.push({
      kind: 'brief',
      key: bk,
      label: 'brief',
      parentKey: qk,
    })
  }

  for (const pr of st.prospects.filter((p) => p.queryKey === qk)) {
    nodes.push({
      kind: 'prospect',
      key: pr.prospectKey,
      label: 'prospect',
      parentKey: pr.briefKey || qk,
      meta: pr.bookKey,
    })
    if (pr.bookKey) bookSet.add(pr.bookKey)
  }

  const solutionSeen = new Set<string>()
  for (const edge of st.inferEdges.filter((e) => e.queryKey === qk)) {
    nodes.push({
      kind: 'infer',
      key: edge.inferKey,
      label: edge.role || 'infer',
      parentKey: edge.solutionKey || qk,
      meta: edge.bookKeys.join(' · '),
    })
    for (const bk of edge.bookKeys) bookSet.add(bk)
    if (edge.solutionKey && !solutionSeen.has(edge.solutionKey)) {
      solutionSeen.add(edge.solutionKey)
      nodes.push({
        kind: 'solution',
        key: edge.solutionKey,
        label: 'solution',
        parentKey: qk,
        meta: edge.conclusion?.slice(0, 80),
      })
    }
  }

  for (const path of st.paths.filter((p) => p.queryKey === qk)) {
    nodes.push({
      kind: 'path',
      key: path.pathKey,
      label: 'path',
      parentKey: path.solutionKey || qk,
      meta: path.conclusion?.slice(0, 80),
    })
    for (const bk of path.bookKeysSequence ?? []) bookSet.add(bk)
  }

  for (const n of st.norms.filter((x) => x.queryKey === qk)) {
    nodes.push({
      kind: 'norm',
      key: n.normKey,
      label: 'norm',
      parentKey: n.pathKey || qk,
    })
  }

  for (const nb of st.neighbours.filter(
    (x) => x.nowQueryKey === qk || x.historicQueryKey === qk,
  )) {
    nodes.push({
      kind: 'neighbour',
      key: nb.neighbourKey,
      label: nb.nowQueryKey === qk ? '→hist' : '←now',
      parentKey: qk,
      meta:
        nb.nowQueryKey === qk ? nb.historicQueryKey : nb.nowQueryKey,
    })
  }

  for (const ru of st.queryReuseLinks.filter((x) => x.fromQueryKey === qk)) {
    nodes.push({
      kind: 'reuse',
      key: ru.reuseKey,
      label: 'reuse',
      parentKey: qk,
      meta: ru.normKey || ru.pathKey,
    })
  }

  const bookKeys = [...bookSet]
  for (const bk of bookKeys) {
    nodes.push({
      kind: 'book',
      key: bk,
      label: 'book',
      parentKey: qk,
    })
  }

  return {
    queryKey: qk,
    question,
    parentQueryKey,
    childQueryKeys,
    ancestorQueryKeys,
    nodes,
    bookKeys,
  }
}

export function groupIncrementNodes(nodes: QueryIncrementNode[]): Record<
  QueryIncrementKind,
  QueryIncrementNode[]
> {
  const empty = (): QueryIncrementNode[] => []
  const out: Record<QueryIncrementKind, QueryIncrementNode[]> = {
    brief: empty(),
    prospect: empty(),
    infer: empty(),
    solution: empty(),
    path: empty(),
    norm: empty(),
    neighbour: empty(),
    reuse: empty(),
    book: empty(),
  }
  for (const n of nodes) out[n.kind].push(n)
  return out
}

/**
 * queryKey 管理：列出当前全部 qk；点开显示该问引出的增量 key 结构图。
 */

import { useMemo, useState } from 'react'
import { useAttentionIo } from '../reasoning/attentionIoStore'
import {
  buildQueryIncrementTree,
  groupIncrementNodes,
  listSettledQueryKeysNewestFirst,
  type QueryIncrementKind,
} from '../reasoning/queryIncrementTree'
import { usePanelSummonStore } from '../reasoning/panelSummonStore'
import { focusSettlementAuditBook } from '../canvas/settleFrame'
import { useIndexGate } from '../reasoning/indexGate'

function short(k: string, n = 12): string {
  const t = k.trim()
  if (t.length <= n) return t
  return `${t.slice(0, 4)}…${t.slice(-4)}`
}

const KIND_ORDER: QueryIncrementKind[] = [
  'solution',
  'path',
  'infer',
  'prospect',
  'brief',
  'norm',
  'neighbour',
  'reuse',
  'book',
]

const KIND_LABEL: Record<QueryIncrementKind, string> = {
  brief: 'briefKey',
  prospect: 'prospectKey',
  infer: 'inferKey',
  solution: 'solutionKey',
  path: 'pathKey',
  norm: 'normKey',
  neighbour: 'neighbourKey',
  reuse: 'reuseKey',
  book: 'bookKey',
}

export function QueryKeyManagerPanel({
  compact = false,
  defaultQueryKey,
  onPickBookKey,
}: {
  compact?: boolean
  /** 结算态默认钉到 pending 的 qk */
  defaultQueryKey?: string | null
  onPickBookKey?: (bookKey: string) => void
}) {
  const settled = useAttentionIo((s) => s.settledQueries)
  const parentOf = useAttentionIo((s) => s.queryParentOf)
  const bookIndex = useIndexGate((s) => s.bookIndex)
  const rows = useMemo(() => {
    void settled
    void parentOf
    return listSettledQueryKeysNewestFirst()
  }, [settled, parentOf])

  const [focusQk, setFocusQk] = useState<string | null>(
    defaultQueryKey ?? null,
  )
  const activeQk =
    focusQk && settled[focusQk]
      ? focusQk
      : defaultQueryKey && settled[defaultQueryKey]
        ? defaultQueryKey
        : rows[0]?.queryKey ?? null

  const tree = useMemo(
    () => (activeQk ? buildQueryIncrementTree(activeQk) : null),
    // recompute when ledger under this qk changes
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [
      activeQk,
      settled,
      useAttentionIo.getState().inferEdges.length,
      useAttentionIo.getState().paths.length,
      useAttentionIo.getState().prospects.length,
      useAttentionIo.getState().norms.length,
    ],
  )

  const grouped = useMemo(
    () => (tree ? groupIncrementNodes(tree.nodes) : null),
    [tree],
  )

  const onSummonKeys = (keys: string[]) => {
    if (!keys.length) return
    usePanelSummonStore.getState().summonKeys(keys)
  }

  const onBook = async (bk: string) => {
    if (onPickBookKey) {
      onPickBookKey(bk)
      return
    }
    if (!bookIndex) return
    await focusSettlementAuditBook({ bookKey: bk, bookIndex })
  }

  return (
    <div
      className={
        compact
          ? 'qk-manager qk-manager--compact'
          : 'qk-manager'
      }
      aria-label="queryKey 管理"
    >
      <header className="qk-manager-head">
        <span className="qk-manager-title">queryKey 管理</span>
        <span className="qk-manager-meta">qk×{rows.length}</span>
      </header>

      {rows.length === 0 ? (
        <p className="qk-manager-empty">尚无 queryKey · 提问后落账</p>
      ) : (
        <ul className="qk-manager-list">
          {rows.map((r) => (
            <li key={r.queryKey}>
              <button
                type="button"
                className={
                  activeQk === r.queryKey
                    ? 'qk-manager-qk active'
                    : 'qk-manager-qk'
                }
                title={r.queryKey}
                onClick={() => setFocusQk(r.queryKey)}
              >
                <code>{short(r.queryKey, 16)}</code>
                <span className="qk-manager-q">
                  {r.question.slice(0, 48)}
                  {r.question.length > 48 ? '…' : ''}
                </span>
              </button>
            </li>
          ))}
        </ul>
      )}

      {tree && grouped ? (
        <div className="qk-manager-tree">
          <div className="qk-manager-tree-head">
            <span>结构图 · </span>
            <code title={tree.queryKey}>{short(tree.queryKey, 18)}</code>
            {tree.parentQueryKey ? (
              <span className="qk-manager-edge">
                ← parent{' '}
                <button
                  type="button"
                  className="qk-manager-link"
                  onClick={() => setFocusQk(tree.parentQueryKey)}
                >
                  {short(tree.parentQueryKey, 12)}
                </button>
              </span>
            ) : (
              <span className="qk-manager-edge">· 根问</span>
            )}
          </div>

          {(tree.childQueryKeys.length > 0 ||
            tree.ancestorQueryKeys.length > 0) && (
            <div className="qk-manager-lineage">
              {tree.ancestorQueryKeys.length > 0 ? (
                <span>
                  祖先{' '}
                  {tree.ancestorQueryKeys.map((a) => (
                    <button
                      key={a}
                      type="button"
                      className="qk-manager-chip"
                      onClick={() => setFocusQk(a)}
                    >
                      {short(a, 10)}
                    </button>
                  ))}
                </span>
              ) : null}
              {tree.childQueryKeys.length > 0 ? (
                <span>
                  子问{' '}
                  {tree.childQueryKeys.map((c) => (
                    <button
                      key={c}
                      type="button"
                      className="qk-manager-chip"
                      onClick={() => setFocusQk(c)}
                    >
                      {short(c, 10)}
                    </button>
                  ))}
                </span>
              ) : null}
            </div>
          )}

          <div className="qk-manager-flow" aria-label="增量结构">
            <div className="qk-manager-root">
              qk → 增量
              <button
                type="button"
                className="qk-manager-chip"
                onClick={() =>
                  onSummonKeys(
                    tree.nodes
                      .filter((n) => n.kind !== 'book')
                      .map((n) => n.key)
                      .slice(0, 24),
                  )
                }
              >
                调取本问微球
              </button>
            </div>
            {KIND_ORDER.map((kind) => {
              const list = grouped[kind]
              if (!list.length) return null
              return (
                <div key={kind} className="qk-manager-branch">
                  <div className="qk-manager-branch-label">
                    {KIND_LABEL[kind]} ×{list.length}
                  </div>
                  <ul className="qk-manager-branch-keys">
                    {list.map((n) => (
                      <li key={`${kind}:${n.key}`}>
                        <button
                          type="button"
                          className={`qk-manager-chip kind-${kind}`}
                          title={
                            n.meta
                              ? `${n.key}\n${n.meta}`
                              : n.key
                          }
                          onClick={() => {
                            if (kind === 'book') void onBook(n.key)
                            else onSummonKeys([n.key])
                          }}
                        >
                          {short(n.key, 14)}
                          {n.label && n.label !== KIND_LABEL[kind]
                            ? ` · ${n.label.slice(0, 16)}`
                            : ''}
                        </button>
                      </li>
                    ))}
                  </ul>
                </div>
              )
            })}
          </div>
        </div>
      ) : null}
    </div>
  )
}

