/**
 * 写信台提示 ↔ 输入框之间的自由幕布：
 * 一级历史 queryKey → 点开 pathKey → 展开解法详情（conclusion / steps / bookKey）
 * bookKey 点击上球审计。
 */

import { useEffect, useMemo, useState } from 'react'
import { useAttentionIo } from '../reasoning/attentionIoStore'
import { useIndexGate } from '../reasoning/indexGate'
import type { BookIndex } from '../reasoning/pipelineA'
import { useDocuverse } from '../canvas/store'
import {
  focusSettlementAuditBook,
  exitSettlementFrame,
} from '../canvas/settleFrame'
import { formatDirectedPathIncrementReturn } from '../arch/pathIncrementReturn'
import { runAutoFlow } from '../reasoning/autoFlow'
import { newLlmCallId } from '../reasoning/settleMint'
import { listSettledQueryKeysNewestFirst } from '../reasoning/queryIncrementTree'
import { usePanelSummonStore } from '../reasoning/panelSummonStore'

function short(k: string, n = 10): string {
  const t = k.trim()
  if (t.length <= n) return t
  return `${t.slice(0, 4)}…${t.slice(-4)}`
}

type PathRow = {
  pathKey: string
  solutionKey: string
  conclusion: string
  bookKeysSequence: string[]
  steps: Array<{
    inferKey: string
    role: string
    bookKeys: string[]
    inferText: string
  }>
  prospects: Array<{
    prospectKey: string
    briefKey: string
    bookKey: string
    text: string
  }>
}

function BookKeyChips({
  bookKeys,
  activeBook,
  bookIndex,
  onPick,
}: {
  bookKeys: string[]
  activeBook: string | null
  bookIndex: BookIndex | null
  onPick: (bk: string) => void
}) {
  if (bookKeys.length === 0) {
    return <p className="curtain-hint">本解法尚无 bookKey</p>
  }
  return (
    <ul className="curtain-book-chips">
      {bookKeys.map((bk) => {
        const page = bookIndex?.chunks.find((c) => c.key === bk)?.page
        return (
          <li key={bk}>
            <button
              type="button"
              className={
                activeBook === bk ? 'curtain-chip active' : 'curtain-chip'
              }
              title={bk}
              onClick={(e) => {
                e.stopPropagation()
                onPick(bk)
              }}
            >
              {short(bk, 14)}
              {page != null ? ` · p${page + 1}` : ''}
            </button>
          </li>
        )
      })}
    </ul>
  )
}

function buildPathRowsForQuery(
  queryKey: string,
  pendingPath: ReturnType<
    typeof useAttentionIo.getState
  >['pendingPathMatch'],
  paths: ReturnType<typeof useAttentionIo.getState>['paths'],
): PathRow[] {
  const normalize = (row: PathRow): PathRow => {
    const fromSteps = [...new Set(row.steps.flatMap((s) => s.bookKeys))]
    return {
      ...row,
      bookKeysSequence:
        row.bookKeysSequence.length > 0 ? row.bookKeysSequence : fromSteps,
    }
  }

  if (
    pendingPath &&
    pendingPath.queryKey === queryKey &&
    (pendingPath.boundPairs?.length || pendingPath.pathKeys?.length)
  ) {
    const pairs = pendingPath.boundPairs ?? []
    if (pairs.length > 0) {
      return pairs.map((p) => {
        const rec = paths.find((x) => x.pathKey === p.pathKey)
        return normalize({
          pathKey: p.pathKey,
          solutionKey: p.solutionKey || rec?.solutionKey || '',
          conclusion: p.conclusion || rec?.conclusion || '',
          bookKeysSequence: p.bookKeysSequence?.length
            ? p.bookKeysSequence
            : p.sharedBookKeys ?? [],
          steps:
            p.steps?.map((s) => ({
              inferKey: s.inferKey,
              role: s.role,
              bookKeys: s.bookKeys,
              inferText: s.inferText,
            })) ??
            rec?.steps?.map((s) => ({
              inferKey: s.inferKey,
              role: s.role,
              bookKeys: s.bookKeys,
              inferText: s.infer,
            })) ??
            [],
          prospects: (p.prospects ?? []).map((pr) => ({
            prospectKey: pr.prospectKey,
            briefKey: pr.briefKey,
            bookKey: pr.bookKey,
            text: pr.text,
          })),
        })
      })
    }
    return (pendingPath.pathKeys ?? []).map((pathKey) => {
      const rec = paths.find((p) => p.pathKey === pathKey)
      return normalize({
        pathKey,
        solutionKey: rec?.solutionKey ?? '',
        conclusion: rec?.conclusion ?? '',
        bookKeysSequence: rec?.bookKeysSequence ?? [],
        steps:
          rec?.steps?.map((s) => ({
            inferKey: s.inferKey,
            role: s.role,
            bookKeys: s.bookKeys,
            inferText: s.infer,
          })) ?? [],
        prospects: [],
      })
    })
  }

  return paths
    .filter((p) => p.queryKey === queryKey)
    .map((rec) =>
      normalize({
        pathKey: rec.pathKey,
        solutionKey: rec.solutionKey ?? '',
        conclusion: rec.conclusion ?? '',
        bookKeysSequence: rec.bookKeysSequence ?? [],
        steps:
          rec.steps?.map((s) => ({
            inferKey: s.inferKey,
            role: s.role,
            bookKeys: s.bookKeys,
            inferText: s.infer,
          })) ?? [],
        prospects: [],
      }),
    )
}

export function QueryPathCurtain() {
  const settled = useAttentionIo((s) => s.settledQueries)
  const pendingPath = useAttentionIo((s) => s.pendingPathMatch)
  const paths = useAttentionIo((s) => s.paths)
  const bookIndex = useIndexGate((s) => s.bookIndex)

  const qkRows = useMemo(() => {
    void settled
    return listSettledQueryKeysNewestFirst()
  }, [settled])

  const [focusQk, setFocusQk] = useState<string | null>(null)
  const [focusPathKey, setFocusPathKey] = useState<string | null>(null)
  const [focusStepIdx, setFocusStepIdx] = useState<number | null>(null)
  const [activeBook, setActiveBook] = useState<string | null>(null)
  const [selectedPaths, setSelectedPaths] = useState<Set<string>>(new Set())
  const [busy, setBusy] = useState(false)
  const [status, setStatus] = useState<string | null>(null)

  const activeQk =
    focusQk && settled[focusQk]
      ? focusQk
      : pendingPath?.queryKey && settled[pendingPath.queryKey]
        ? pendingPath.queryKey
        : qkRows[0]?.queryKey ?? null

  const pathRows = useMemo(
    () => (activeQk ? buildPathRowsForQuery(activeQk, pendingPath, paths) : []),
    [activeQk, pendingPath, paths],
  )

  const pendingForActive =
    Boolean(pendingPath && pendingPath.queryKey === activeQk)

  // 进入待结算问：收起刷屏微球，默认展开该 qk / 首 path
  useEffect(() => {
    if (!pendingPath) return
    usePanelSummonStore.getState().dismissAll()
    setFocusQk(pendingPath.queryKey)
    const rows = buildPathRowsForQuery(
      pendingPath.queryKey,
      pendingPath,
      useAttentionIo.getState().paths,
    )
    setSelectedPaths(new Set(rows.map((r) => r.pathKey)))
    if (rows[0]) {
      setFocusPathKey(rows[0].pathKey)
      setFocusStepIdx(0)
    }
    useAttentionIo.getState().setDeskPrompt(
      `结算 · 解法 path×${rows.length} · 确认/撤销` +
        (pendingPath.question
          ? ` · ${pendingPath.question.slice(0, 40)}`
          : ''),
    )
  }, [pendingPath?.createdAt, pendingPath?.queryKey])

  // 预物化当前解法 bookKeys → 球
  useEffect(() => {
    if (!bookIndex || !focusPathKey) return
    const row = pathRows.find((r) => r.pathKey === focusPathKey)
    if (!row || row.bookKeysSequence.length === 0) return
    let cancelled = false
    void (async () => {
      const store = useDocuverse.getState()
      store.clearAuditSphereStrands()
      usePanelSummonStore.getState().dismissAll()
      const strands = new Set<number>()
      for (const bk of row.bookKeysSequence) {
        const chunk = bookIndex.chunks.find((c) => c.key === bk)
        if (chunk) strands.add(chunk.page)
      }
      for (const strand of strands) {
        if (cancelled) return
        await store.ensurePageForAudit(strand, { focus: false })
        store.registerAuditSphereStrand(strand)
      }
      if (cancelled) return
      const first =
        row.steps[focusStepIdx ?? 0]?.bookKeys[0] ?? row.bookKeysSequence[0]
      if (first) {
        setActiveBook(first)
        const ok = await focusSettlementAuditBook({
          bookKey: first,
          bookIndex,
        })
        setStatus(
          ok
            ? `上球 · ${short(first, 16)}`
            : `上球失败 · 查 bookIndex/页壳 · ${short(first, 16)}`,
        )
      }
    })()
    return () => {
      cancelled = true
    }
  }, [focusPathKey, bookIndex?.docId, pathRows])

  const onPickBook = async (bk: string) => {
    if (!bookIndex) {
      setStatus('无 bookIndex · 请先上传 PDF')
      return
    }
    setActiveBook(bk)
    usePanelSummonStore.getState().dismissAll()
    const ok = await focusSettlementAuditBook({ bookKey: bk, bookIndex })
    const strand = bookIndex.chunks.find((c) => c.key === bk)?.page
    const page = useDocuverse
      .getState()
      .pages.find((p) => p.strandIndex === strand)
    setStatus(
      ok
        ? `上球 · ${short(bk, 14)} · s${strand ?? '?'}${page?.imageUrl ? ' · 有图' : ' · 纸页'}`
        : `上球失败 · ${short(bk, 14)} · strand=${strand ?? '∅'}`,
    )
  }

  const onConfirmPaths = () => {
    if (!pendingPath || busy || selectedPaths.size === 0) return
    setBusy(true)
    try {
      const io = useAttentionIo.getState()
      const picked = pathRows.filter((r) => selectedPaths.has(r.pathKey))
      for (const row of picked) {
        io.confirmPathMatch(row.pathKey)
      }
      setStatus(`已确认解法 ×${picked.length}`)
      exitSettlementFrame()
      io.clearPendingPathMatch()
      io.clearDeskPrompt()
    } finally {
      setBusy(false)
    }
  }

  const onRevokePaths = () => {
    if (!pendingPath || busy) return
    setBusy(true)
    try {
      useAttentionIo.getState().clearPendingPathMatch()
      useAttentionIo.getState().clearDeskPrompt()
      exitSettlementFrame()
      setStatus('已撤销结算')
    } finally {
      setBusy(false)
    }
  }

  const onDeepen = async () => {
    if (!pendingPath || busy || !bookIndex) return
    setBusy(true)
    try {
      await runAutoFlow({
        question: pendingPath.question || '',
        bookIndex,
        llmCallId: newLlmCallId(),
        deepen: true,
      })
    } finally {
      setBusy(false)
    }
  }

  void formatDirectedPathIncrementReturn

  return (
    <div className="query-path-curtain" aria-label="queryKey 幕布">
      <div className="curtain-layer curtain-qk">
        <div className="curtain-layer-label">历史 queryKey</div>
        {qkRows.length === 0 ? (
          <p className="curtain-hint">尚无 queryKey</p>
        ) : (
          <ul className="curtain-qk-list">
            {qkRows.map((r) => (
              <li key={r.queryKey}>
                <button
                  type="button"
                  className={
                    activeQk === r.queryKey
                      ? 'curtain-qk-btn active'
                      : 'curtain-qk-btn'
                  }
                  title={r.queryKey}
                  onClick={() => {
                    setFocusQk(r.queryKey)
                    setFocusPathKey(null)
                    setFocusStepIdx(null)
                  }}
                >
                  <code>{short(r.queryKey, 16)}</code>
                  <span>
                    {r.question.slice(0, 42)}
                    {r.question.length > 42 ? '…' : ''}
                  </span>
                </button>
              </li>
            ))}
          </ul>
        )}
      </div>

      {activeQk ? (
        <div className="curtain-layer curtain-paths">
          <div className="curtain-layer-label">
            pathKey ·{' '}
            <code title={activeQk}>{short(activeQk, 14)}</code>
            {' · '}
            path×{pathRows.length}
            {pendingForActive ? ' · 待结算' : ''}
          </div>
          {pathRows.length === 0 ? (
            <p className="curtain-hint">此问尚无 path</p>
          ) : (
            <ul className="curtain-path-list">
              {pathRows.map((row) => (
                <li key={row.pathKey}>
                  <button
                    type="button"
                    className={
                      focusPathKey === row.pathKey
                        ? 'curtain-path-btn active'
                        : 'curtain-path-btn'
                    }
                    onClick={() => {
                      setFocusPathKey(row.pathKey)
                      setFocusStepIdx(0)
                      const bk =
                        row.steps[0]?.bookKeys[0] ?? row.bookKeysSequence[0]
                      if (bk) void onPickBook(bk)
                    }}
                  >
                    {pendingForActive ? (
                      <input
                        type="checkbox"
                        checked={selectedPaths.has(row.pathKey)}
                        onChange={(e) => {
                          e.stopPropagation()
                          setSelectedPaths((prev) => {
                            const n = new Set(prev)
                            if (n.has(row.pathKey)) n.delete(row.pathKey)
                            else n.add(row.pathKey)
                            return n
                          })
                        }}
                        onClick={(e) => e.stopPropagation()}
                      />
                    ) : null}
                    <code title={row.pathKey}>{short(row.pathKey, 16)}</code>
                    {row.solutionKey ? (
                      <span className="curtain-sk">
                        sk={short(row.solutionKey, 8)}
                      </span>
                    ) : null}
                    <span className="curtain-path-preview">
                      {(row.conclusion || '').slice(0, 56)}
                      {(row.conclusion || '').length > 56 ? '…' : ''}
                    </span>
                  </button>
                </li>
              ))}
            </ul>
          )}
        </div>
      ) : null}

      {focusPathKey
        ? (() => {
            const row = pathRows.find((r) => r.pathKey === focusPathKey)
            if (!row) return null
            return (
              <div className="curtain-layer curtain-detail">
                <div className="curtain-detail-head">
                  query{' '}
                  <code title={activeQk ?? ''}>
                    {short(activeQk ?? '', 16)}
                  </code>
                  {settled[activeQk ?? ''] ? (
                    <span className="curtain-q">
                      {' '}
                      · {settled[activeQk!]!.slice(0, 48)}
                    </span>
                  ) : null}
                </div>
                <div className="curtain-k">
                  解法{' '}
                  <code title={row.pathKey}>{short(row.pathKey, 18)}</code>
                  {row.solutionKey
                    ? ` · sk=${short(row.solutionKey, 10)}`
                    : ''}
                </div>
                <div className="curtain-k">conclusion · 解法总览</div>
                <pre className="curtain-text">
                  {row.conclusion || '（无 conclusion）'}
                </pre>

                <div className="curtain-k">
                  本解法 bookKey×{row.bookKeysSequence.length}
                </div>
                <BookKeyChips
                  bookKeys={row.bookKeysSequence}
                  activeBook={activeBook}
                  bookIndex={bookIndex}
                  onPick={(bk) => void onPickBook(bk)}
                />

                <div className="curtain-k">
                  steps×{row.steps.length} · 点步 / 点门牌 → 上球
                </div>
                <ul className="curtain-steps">
                  {row.steps.map((st, idx) => {
                    const stepActive = focusStepIdx === idx
                    const stepBooks =
                      st.bookKeys.length > 0
                        ? st.bookKeys
                        : row.bookKeysSequence
                    return (
                      <li
                        key={st.inferKey || idx}
                        className={
                          stepActive
                            ? 'curtain-step active'
                            : 'curtain-step'
                        }
                      >
                        <button
                          type="button"
                          className="curtain-step-btn"
                          onClick={() => {
                            setFocusStepIdx(idx)
                            const bk = stepBooks[0]
                            if (bk) void onPickBook(bk)
                          }}
                        >
                          <span className="curtain-k">
                            步骤 {idx + 1}
                            {st.role ? ` · ${st.role}` : ''}
                            {' · '}
                            <code title={st.inferKey}>
                              {short(st.inferKey || '∅', 10)}
                            </code>
                          </span>
                          <pre className="curtain-text">
                            {st.inferText || '（空）'}
                          </pre>
                        </button>
                        <div className="curtain-k">
                          本步 bookKey×{stepBooks.length}
                        </div>
                        <BookKeyChips
                          bookKeys={stepBooks}
                          activeBook={stepActive ? activeBook : null}
                          bookIndex={bookIndex}
                          onPick={(bk) => {
                            setFocusStepIdx(idx)
                            void onPickBook(bk)
                          }}
                        />
                      </li>
                    )
                  })}
                </ul>

                {(() => {
                  const stepBooks =
                    focusStepIdx != null
                      ? new Set(
                          row.steps[focusStepIdx]?.bookKeys?.length
                            ? row.steps[focusStepIdx]!.bookKeys
                            : row.bookKeysSequence,
                        )
                      : null
                  const stepProspects = stepBooks
                    ? row.prospects.filter((pr) =>
                        stepBooks.has(pr.bookKey),
                      )
                    : row.prospects
                  return (
                    <>
                      <div className="curtain-k">
                        prospect 载荷
                        {stepBooks
                          ? `（本步）×${stepProspects.length}`
                          : `×${row.prospects.length}`}
                      </div>
                      {stepProspects.length > 0 ? (
                        <ul className="curtain-prospects">
                          {stepProspects.map((pr) => (
                            <li key={pr.prospectKey}>
                              <code title={pr.prospectKey}>
                                {short(pr.prospectKey, 12)}
                              </code>
                              {' · '}
                              <button
                                type="button"
                                className="curtain-chip"
                                title={pr.bookKey}
                                onClick={() => void onPickBook(pr.bookKey)}
                              >
                                {short(pr.bookKey, 12)}
                              </button>
                              <pre className="curtain-text">
                                {pr.text || '（空）'}
                              </pre>
                            </li>
                          ))}
                        </ul>
                      ) : (
                        <p className="curtain-hint">暂无 prospect</p>
                      )}
                    </>
                  )
                })()}
              </div>
            )
          })()
        : activeQk ? (
            <p className="curtain-hint">点上方 pathKey 展开解法详情</p>
          ) : null}

      {pendingForActive ? (
        <div className="curtain-actions">
          <button
            type="button"
            className="curtain-btn primary"
            disabled={busy || selectedPaths.size === 0}
            onClick={onConfirmPaths}
          >
            确认
          </button>
          <button
            type="button"
            className="curtain-btn danger"
            disabled={busy}
            onClick={onRevokePaths}
          >
            撤销
          </button>
          <button
            type="button"
            className="curtain-btn"
            disabled={busy}
            onClick={() => void onDeepen()}
          >
            深化再跑
          </button>
        </div>
      ) : null}

      {status ? <p className="curtain-status">{status}</p> : null}
    </div>
  )
}

