/** 相机正对球壳上该 strand 的槽位（结算球按 audit 列表紧凑排布） */
function cameraFrameForStrand(
  strand: number,
  kind: SettlementKind,
  activeBookKey: string,
): LockedSettlementFrame {
  const st = useDocuverse.getState()
  const audit = st.auditSphereStrands
  const compactIdx = audit.indexOf(strand)
  const total = Math.max(audit.length > 0 ? audit.length : st.pages.length, 1)
  const slot = compactIdx >= 0 ? compactIdx : Math.max(0, strand)
  const home = pageHomePosition(slot, total)
  const radial = new THREE.Vector3(home[0], 0, home[2])
  if (radial.lengthSq() < 1e-6) radial.set(0, 0, 1)
  radial.normalize()
  const eyeDist = Math.max(innerSphereRadius(total) * 2.35, 6.5)
  const eyeV = radial.clone().multiplyScalar(eyeDist)
  eyeV.y = home[1] + 0.35
  const lookAt: [number, number, number] = [home[0], home[1], home[2]]
  const eye: [number, number, number] = [eyeV.x, eyeV.y, eyeV.z]
  const { yaw, pitch } = radialToYawPitch(eyeV)
  return {
    kind,
    eye,
    lookAt,
    yaw,
    pitch,
    distance: eyeV.length(),
    slotRingAngle: 0,
    activeBookKey,
  }
}

