/**
 * queryKey 无限幕布：最小可点节点；点选后由上层审计面板展示该问内容。
 */

import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type PointerEvent as ReactPointerEvent,
} from 'react'
import { useAttentionIo } from '../reasoning/attentionIoStore'
import { listSettledQueryKeysNewestFirst } from '../reasoning/queryIncrementTree'

function short(k: string, n = 10): string {
  const t = k.trim()
  if (t.length <= n) return t
  return `${t.slice(0, 4)}…${t.slice(-4)}`
}

type NodePos = { x: number; y: number }

function defaultLayout(
  keys: string[],
  parentOf: Record<string, string>,
): Record<string, NodePos> {
  const pos: Record<string, NodePos> = {}
  const roots = keys.filter((k) => !parentOf[k] || !keys.includes(parentOf[k]!))
  const placed = new Set<string>()
  let rootCol = 0
  const placeTree = (qk: string, depth: number, col: number) => {
    if (placed.has(qk)) return
    placed.add(qk)
    pos[qk] = { x: 80 + col * 140, y: 60 + depth * 90 }
    const children = keys.filter((k) => parentOf[k] === qk)
    children.forEach((c, i) => placeTree(c, depth + 1, col + i))
  }
  roots.forEach((r, i) => {
    placeTree(r, 0, rootCol)
    rootCol += Math.max(1, keys.filter((k) => parentOf[k] === r).length || 1)
  })
  keys.forEach((k, i) => {
    if (!pos[k]) pos[k] = { x: 80 + (i % 5) * 140, y: 60 + Math.floor(i / 5) * 90 }
  })
  return pos
}

export function QueryKeyInfiniteCanvas({
  activeQueryKey,
  onSelectQueryKey,
}: {
  activeQueryKey: string | null
  onSelectQueryKey: (queryKey: string) => void
}) {
  const settled = useAttentionIo((s) => s.settledQueries)
  const parentOf = useAttentionIo((s) => s.queryParentOf)

  const rows = useMemo(() => {
    void settled
    return listSettledQueryKeysNewestFirst()
  }, [settled])

  const keys = useMemo(() => rows.map((r) => r.queryKey), [rows])
  const qText = useMemo(() => {
    const m: Record<string, string> = {}
    for (const r of rows) m[r.queryKey] = r.question
    return m
  }, [rows])

  const [positions, setPositions] = useState<Record<string, NodePos>>({})
  const [pan, setPan] = useState({ x: 0, y: 0 })
  const [zoom, setZoom] = useState(1)
  const drag = useRef<
    | { kind: 'pan'; ox: number; oy: number; px: number; py: number }
    | { kind: 'node'; key: string; ox: number; oy: number; nx: number; ny: number }
    | null
  >(null)
  const moved = useRef(false)

  useEffect(() => {
    setPositions((prev) => {
      const next = { ...prev }
      const fresh = keys.filter((k) => !next[k])
      if (fresh.length === 0) return prev
      const laid = defaultLayout(keys, parentOf)
      for (const k of fresh) next[k] = laid[k] ?? { x: 80, y: 80 }
      return next
    })
  }, [keys, parentOf])

  const edges = useMemo(() => {
    const out: Array<{ from: string; to: string }> = []
    for (const k of keys) {
      const p = parentOf[k]
      if (p && keys.includes(p)) out.push({ from: p, to: k })
    }
    return out
  }, [keys, parentOf])

  const onPointerDownBg = (e: ReactPointerEvent) => {
    if (e.button !== 0) return
    ;(e.currentTarget as HTMLElement).setPointerCapture(e.pointerId)
    drag.current = {
      kind: 'pan',
      ox: e.clientX,
      oy: e.clientY,
      px: pan.x,
      py: pan.y,
    }
    moved.current = false
  }

  const onPointerMove = (e: ReactPointerEvent) => {
    const d = drag.current
    if (!d) return
    const dx = e.clientX - d.ox
    const dy = e.clientY - d.oy
    if (Math.hypot(dx, dy) > 3) moved.current = true
    if (d.kind === 'pan') {
      setPan({ x: d.px + dx, y: d.py + dy })
    } else {
      setPositions((prev) => ({
        ...prev,
        [d.key]: {
          x: d.nx + dx / zoom,
          y: d.ny + dy / zoom,
        },
      }))
    }
  }

  const onPointerUp = () => {
    drag.current = null
  }

  const onWheel = useCallback((e: React.WheelEvent) => {
    e.preventDefault()
    setZoom((z) => Math.min(2.2, Math.max(0.45, z * (e.deltaY > 0 ? 0.92 : 1.08))))
  }, [])

  const labelOf = (qk: string, i: number) => {
    const n = rows.length - i
    return `q${n}`
  }

  return (
    <div
      className="qk-infinite"
      onPointerDown={onPointerDownBg}
      onPointerMove={onPointerMove}
      onPointerUp={onPointerUp}
      onPointerCancel={onPointerUp}
      onWheel={onWheel}
      role="application"
      aria-label="queryKey 无限幕布"
    >
      <div className="qk-infinite-hint">
        拖动画布平移 · 滚轮缩放 · 点节点打开上方审计
      </div>
      <div
        className="qk-infinite-world"
        style={{
          transform: `translate(${pan.x}px, ${pan.y}px) scale(${zoom})`,
        }}
      >
        <svg className="qk-infinite-edges" aria-hidden>
          {edges.map((e) => {
            const a = positions[e.from]
            const b = positions[e.to]
            if (!a || !b) return null
            return (
              <line
                key={`${e.from}->${e.to}`}
                x1={a.x + 36}
                y1={a.y + 18}
                x2={b.x + 36}
                y2={b.y + 18}
                stroke="rgba(232,196,120,0.35)"
                strokeWidth={1.5}
              />
            )
          })}
        </svg>
        {rows.map((r, i) => {
          const p = positions[r.queryKey] ?? { x: 80, y: 80 }
          const active = activeQueryKey === r.queryKey
          return (
            <button
              key={r.queryKey}
              type="button"
              className={active ? 'qk-node active' : 'qk-node'}
              style={{ left: p.x, top: p.y }}
              title={`${r.queryKey}\n${r.question}`}
              onPointerDown={(e) => {
                e.stopPropagation()
                ;(e.currentTarget as HTMLElement).setPointerCapture(e.pointerId)
                drag.current = {
                  kind: 'node',
                  key: r.queryKey,
                  ox: e.clientX,
                  oy: e.clientY,
                  nx: p.x,
                  ny: p.y,
                }
                moved.current = false
              }}
              onPointerUp={(e) => {
                e.stopPropagation()
                const wasDrag = moved.current
                drag.current = null
                if (!wasDrag) onSelectQueryKey(r.queryKey)
              }}
            >
              <span className="qk-node-label">{labelOf(r.queryKey, i)}</span>
              <code className="qk-node-key">{short(r.queryKey, 12)}</code>
              <span className="qk-node-q">
                {(qText[r.queryKey] || '').slice(0, 18)}
                {(qText[r.queryKey] || '').length > 18 ? '…' : ''}
              </span>
            </button>
          )
        })}
        {rows.length === 0 ? (
          <p className="qk-infinite-empty">提问后此处出现可点 queryKey 节点</p>
        ) : null}
      </div>
    </div>
  )
}

input.new_string:
  const onSelectQk = (qk: string) => {
    setFocusQk(qk)
    useAttentionIo.getState().openQueryKey(qk)
    const rows = buildPathRowsForQuery(
      qk,
      useAttentionIo.getState().pendingPathMatch,
      useAttentionIo.getState().paths,
    )
    if (rows[0]) {
      setFocusPathKey(rows[0].pathKey)
      setFocusStepIdx(0)
      setSelectedPaths(new Set(rows.map((r) => r.pathKey)))
      const bk = rows[0].steps[0]?.bookKeys[0] ?? rows[0].bookKeysSequence[0]
      if (bk) void onPickBook(bk)
    } else {
      setFocusPathKey(null)
      setFocusStepIdx(null)
    }
  }

  return (
    <div className="query-path-curtain query-path-curtain--split" aria-label="queryKey 幕布">
      <div className="curtain-audit" aria-label="解法审计">
        {!activeQk ? (
          <p className="curtain-hint">
            下方幕布点选 queryKey → 此处呈现该问的 path / steps / bookKey
          </p>
        ) : (
          <>
            <div className="curtain-now-qk">
              <span className="curtain-layer-label">审计 · queryKey</span>
              <code title={activeQk}>{short(activeQk, 18)}</code>
              <span className="curtain-q">
                {settled[activeQk]?.slice(0, 56) || ''}
                {(settled[activeQk]?.length ?? 0) > 56 ? '…' : ''}
              </span>
            </div>

            <div className="curtain-layer curtain-paths">
              <div className="curtain-layer-label">
                path×{pathRows.length}
                {pendingForActive ? ' · 待结算' : ''}
              </div>
              {pathRows.length === 0 ? (
                <p className="curtain-hint">此问尚无 path</p>
              ) : (
                <ul className="curtain-path-list">
                  {pathRows.map((row) => (
                    <li key={row.pathKey}>
                      <button
                        type="button"
                        className={
                          focusPathKey === row.pathKey
                            ? 'curtain-path-btn active'
                            : 'curtain-path-btn'
                        }
                        onClick={() => {
                          setFocusPathKey(row.pathKey)
                          setFocusStepIdx(0)
                          const bk =
                            row.steps[0]?.bookKeys[0] ??
                            row.bookKeysSequence[0]
                          if (bk) void onPickBook(bk)
                        }}
                      >
                        {pendingForActive ? (
                          <input
                            type="checkbox"
                            checked={selectedPaths.has(row.pathKey)}
                            onChange={(e) => {
                              e.stopPropagation()
                              setSelectedPaths((prev) => {
                                const n = new Set(prev)
                                if (n.has(row.pathKey)) n.delete(row.pathKey)
                                else n.add(row.pathKey)
                                return n
                              })
                            }}
                            onClick={(e) => e.stopPropagation()}
                          />
                        ) : null}
                        <code title={row.pathKey}>
                          {short(row.pathKey, 16)}
                        </code>
                        {row.solutionKey ? (
                          <span className="curtain-sk">
                            sk={short(row.solutionKey, 8)}
                          </span>
                        ) : null}
                        <span className="curtain-path-preview">
                          {(row.conclusion || '').slice(0, 56)}
                          {(row.conclusion || '').length > 56 ? '…' : ''}
                        </span>
                      </button>
                    </li>
                  ))}
                </ul>
              )}
            </div>

            {focusPathKey
              ? (() => {
                  const row = pathRows.find((r) => r.pathKey === focusPathKey)
                  if (!row) return null
                  return (
                    <div className="curtain-layer curtain-detail">
                      <div className="curtain-k">conclusion · 解法总览</div>
                      <pre className="curtain-text">
                        {row.conclusion || '（无 conclusion）'}
                      </pre>
                      <div className="curtain-k">
                        本解法 bookKey×{row.bookKeysSequence.length}
                      </div>
                      <BookKeyChips
                        bookKeys={row.bookKeysSequence}
                        activeBook={activeBook}
                        bookIndex={bookIndex}
                        onPick={(bk) => void onPickBook(bk)}
                      />
                      <div className="curtain-k">
                        steps×{row.steps.length} · 点步 / 点门牌 → 上球
                      </div>
                      <ul className="curtain-steps">
                        {row.steps.map((st, idx) => {
                          const stepActive = focusStepIdx === idx
                          const stepBooks =
                            st.bookKeys.length > 0
                              ? st.bookKeys
                              : row.bookKeysSequence
                          return (
                            <li
                              key={st.inferKey || idx}
                              className={
                                stepActive
                                  ? 'curtain-step active'
                                  : 'curtain-step'
                              }
                            >
                              <button
                                type="button"
                                className="curtain-step-btn"
                                onClick={() => {
                                  setFocusStepIdx(idx)
                                  const bk = stepBooks[0]
                                  if (bk) void onPickBook(bk)
                                }}
                              >
                                <span className="curtain-k">
                                  步骤 {idx + 1}
                                  {st.role ? ` · ${st.role}` : ''}
                                  {' · '}
                                  <code title={st.inferKey}>
                                    {short(st.inferKey || '∅', 10)}
                                  </code>
                                </span>
                                <pre className="curtain-text">
                                  {st.inferText || '（空）'}
                                </pre>
                              </button>
                              <div className="curtain-k">
                                本步 bookKey×{stepBooks.length}
                              </div>
                              <BookKeyChips
                                bookKeys={stepBooks}
                                activeBook={
                                  stepActive ? activeBook : null
                                }
                                bookIndex={bookIndex}
                                onPick={(bk) => {
                                  setFocusStepIdx(idx)
                                  void onPickBook(bk)
                                }}
                              />
                            </li>
                          )
                        })}
                      </ul>
                      {(() => {
                        const stepBooks =
                          focusStepIdx != null
                            ? new Set(
                                row.steps[focusStepIdx]?.bookKeys
                                  ?.length
                                  ? row.steps[focusStepIdx]!.bookKeys
                                  : row.bookKeysSequence,
                              )
                            : null
                        const stepProspects = stepBooks
                          ? row.prospects.filter((pr) =>
                              stepBooks.has(pr.bookKey),
                            )
                          : row.prospects
                        return (
                          <>
                            <div className="curtain-k">
                              prospect 载荷
                              {stepBooks
                                ? `（本步）×${stepProspects.length}`
                                : `×${row.prospects.length}`}
                            </div>
                            {stepProspects.length > 0 ? (
                              <ul className="curtain-prospects">
                                {stepProspects.map((pr) => (
                                  <li key={pr.prospectKey}>
                                    <code title={pr.prospectKey}>
                                      {short(pr.prospectKey, 12)}
                                    </code>
                                    {' · '}
                                    <button
                                      type="button"
                                      className="curtain-chip"
                                      title={pr.bookKey}
                                      onClick={() =>
                                        void onPickBook(pr.bookKey)
                                      }
                                    >
                                      {short(pr.bookKey, 12)}
                                    </button>
                                    <pre className="curtain-text">
                                      {pr.text || '（空）'}
                                    </pre>
                                  </li>
                                ))}
                              </ul>
                            ) : (
                              <p className="curtain-hint">暂无 prospect</p>
                            )}
                          </>
                        )
                      })()}
                    </div>
                  )
                })()
              : activeQk ? (
                  <p className="curtain-hint">点上方 path 展开 steps / bookKey</p>
                ) : null}

            {pendingForActive ? (
              <div className="curtain-actions">
                <button
                  type="button"
                  className="curtain-btn primary"
                  disabled={busy || selectedPaths.size === 0}
                  onClick={onConfirmPaths}
                >
                  确认
                </button>
                <button
                  type="button"
                  className="curtain-btn danger"
                  disabled={busy}
                  onClick={onRevokePaths}
                >
                  撤销
                </button>
              </div>
            ) : null}
            {status ? <p className="curtain-status">{status}</p> : null}
          </>
        )}
      </div>

      <QueryKeyInfiniteCanvas
        activeQueryKey={activeQk}
        onSelectQueryKey={onSelectQk}
      />
    </div>
  )
}

