/**
 * 结算架：复用原球体交互（roaming + swoopToPage）。
 * 仅限制「哪些页上球」，不另造机位/点击逻辑。
 */

import type { BookIndex } from '../reasoning/pipelineA'
import { focusA1KeyOnPdf } from '../reasoning/focusA1Key'
import { useDocuverse } from './store'
import {
  clearPokerYawOffset,
  pageRadialDirection,
  radialToYawPitch,
  readingOuterRadius,
} from './geometry'

export type SettlementKind = 'reuse' | 'path'

type LockedSettlementFrame = {
  kind: SettlementKind
  activeBookKey: string
}

let locked: LockedSettlementFrame | null = null

function pageOfBookKey(
  bookKey: string,
  bookIndex: BookIndex,
): number | null {
  const chunk = bookIndex.chunks.find((c) => c.key === bookKey)
  return chunk ? chunk.page : null
}

/** 回到原球体机位，再按 strand swoop（与常态同一套） */
function ensureRoamingSphere() {
  useDocuverse.setState({
    cameraLens: 'roaming',
    cameraEye: null,
    cameraLookAt: null,
    constructionLinkId: null,
    keyComparePair: null,
    keyCompareTri: null,
    linkFocusId: null,
    viewPan: [0, 0, 0],
    commentLayerExpanded: false,
  })
}

function swoopLikeNormal(strand: number) {
  ensureRoamingSphere()
  const st = useDocuverse.getState()
  if (st.currentStrand !== strand) {
    st.swoopToPage(strand)
    return
  }
  // 同页：原 swoopToPage 会 early-return，补一次朝向
  const total = Math.max(st.pages.length, 1)
  const { yaw, pitch } = radialToYawPitch(pageRadialDirection(strand, total))
  useDocuverse.setState({
    swooping: true,
    viewYaw: yaw,
    viewPitch: pitch,
    viewPan: [0, 0, 0],
    cameraDistance: readingOuterRadius(total),
  })
  window.setTimeout(() => {
    useDocuverse.setState({ swooping: false })
  }, 1100)
}

async function prepareAuditPage(
  bookKey: string,
  bookIndex: BookIndex,
  focus: boolean,
): Promise<number | null> {
  const strand = pageOfBookKey(bookKey, bookIndex)
  if (strand == null) return null
  try {
    const { usePanelSummonStore } = await import(
      '../reasoning/panelSummonStore'
    )
    usePanelSummonStore.getState().dismissAll()
  } catch {
    /* ignore */
  }
  await useDocuverse.getState().ensurePageForAudit(strand, { focus })
  useDocuverse.getState().registerAuditSphereStrand(strand)
  useDocuverse.getState().revealSphereForAudit()
  return strand
}

export async function enterSettlementSingleAnchor(input: {
  kind: SettlementKind
  bookKey: string
  bookIndex: BookIndex
}): Promise<boolean> {
  const strand = await prepareAuditPage(input.bookKey, input.bookIndex, true)
  if (strand == null) return false
  clearPokerYawOffset()
  locked = { kind: input.kind, activeBookKey: input.bookKey }
  swoopLikeNormal(strand)
  focusA1KeyOnPdf({
    key: input.bookKey,
    bookIndex: input.bookIndex,
    swoopToPage: (s) => swoopLikeNormal(s),
  })
  return true
}

/** 点球上页：与常态 swoop 相同 */
export function focusSettlementAuditStrand(strand: number): boolean {
  const st = useDocuverse.getState()
  if (!st.pages.some((p) => p.strandIndex === strand)) return false
  st.registerAuditSphereStrand(strand)
  st.revealSphereForAudit()
  clearPokerYawOffset()
  if (!locked) locked = { kind: 'path', activeBookKey: '' }
  swoopLikeNormal(strand)
  return true
}

export async function focusSettlementAuditBook(input: {
  bookKey: string
  bookIndex: BookIndex
}): Promise<boolean> {
  const strand = await prepareAuditPage(input.bookKey, input.bookIndex, true)
  if (strand == null) return false
  clearPokerYawOffset()
  locked = { kind: 'path', activeBookKey: input.bookKey }
  swoopLikeNormal(strand)
  focusA1KeyOnPdf({
    key: input.bookKey,
    bookIndex: input.bookIndex,
    swoopToPage: (s) => swoopLikeNormal(s),
  })
  return true
}

export async function settlementSelectBookKey(input: {
  bookKey: string
  bookIndex: BookIndex
}): Promise<boolean> {
  if (!locked) {
    return enterSettlementSingleAnchor({
      kind: 'path',
      bookKey: input.bookKey,
      bookIndex: input.bookIndex,
    })
  }
  return focusSettlementAuditBook(input)
}

export function getSettlementFrame(): LockedSettlementFrame | null {
  return locked
}

export function exitSettlementFrame(): void {
  locked = null
  clearPokerYawOffset()
  useDocuverse.getState().clearAuditSphereStrands()
  useDocuverse.getState().hideSphereAfterAudit()
  ensureRoamingSphere()
  useDocuverse.setState({
    settlementSphereEpoch: useDocuverse.getState().settlementSphereEpoch + 1,
  })
}

import { Canvas } from '@react-three/fiber'
import { Suspense, useCallback, useState } from 'react'
import * as THREE from 'three'
import { useDocuverse } from './store'
import { PageMesh } from './PageMesh'
import { BeamLayer } from './BeamLayer'
import { EmphasisBeamLayer } from './EmphasisBeamLayer'
import { CameraRig, OrbitControlsProxy } from './CameraRig'
import { innerSphereRadius, pageHomePosition } from './geometry'
import { OcrComparePlane } from './OcrComparePlane'
import { RelationPasteLayer } from './RelationPasteLayer'
import { KeyPanelLayer } from './KeyPanelLayer'
import { EmphasisPenController } from './EmphasisPenController'

const noHit = (() => undefined) as unknown as THREE.Mesh['raycast']

export function CvsScene({
  settlementAudit = false,
}: {
  /**
   * 结算：复用原球体全部交互；仅渲染 infer 激活页（不渲全库页）。
   */
  settlementAudit?: boolean
}) {
  const [canvasKey, setCanvasKey] = useState(0)
  const onCanvasCreated = useCallback(({ gl }: { gl: THREE.WebGLRenderer }) => {
    const canvas = gl.domElement
    const onLost = (e: Event) => {
      e.preventDefault()
      window.setTimeout(() => setCanvasKey((k) => k + 1), 50)
    }
    canvas.addEventListener('webglcontextlost', onLost, { once: true })
  }, [])

  const pages = useDocuverse((s) => s.pages)
  const connections = useDocuverse((s) => s.connections)
  const currentStrand = useDocuverse((s) => s.currentStrand)
  const companionStrand = useDocuverse((s) => s.companionStrand)
  const currentConnectionId = useDocuverse((s) => s.currentConnectionId)
  const selectConnection = useDocuverse((s) => s.selectConnection)
  const swoopToPage = useDocuverse((s) => s.swoopToPage)
  const settlementSphereEpoch = useDocuverse((s) => s.settlementSphereEpoch)
  const auditSphereStrands = useDocuverse((s) => s.auditSphereStrands)

  const auditSet =
    settlementAudit && auditSphereStrands.length > 0
      ? new Set(auditSphereStrands)
      : null
  // 结算：只挂激活页；槽位仍用全书自然坐标，交互与常态同一套 swoop
  const visiblePages = settlementAudit
    ? pages.filter((p) =>
        auditSet ? auditSet.has(p.strandIndex) : Boolean(p.imageUrl),
      )
    : pages
  const ringTotal = Math.max(pages.length, 1)
  const ringR = innerSphereRadius(ringTotal)
  void settlementSphereEpoch

  return (
    <Canvas
      key={canvasKey}
      onCreated={onCanvasCreated}
      shadows={false}
      dpr={[1, 1.5]}
      camera={{
        fov: 50,
        near: 0.05,
        far: 50000,
        position: [0, ringR * 1.55, ringR * 1.55],
      }}
      style={{ width: '100%', height: '100%' }}
      performance={{ min: 0.5 }}
    >
      <color attach="background" args={['#0b0e14']} />
      <ambientLight intensity={0.75} />
      <directionalLight position={[8, 28, 6]} intensity={0.95} />
      <fog attach="fog" args={['#0b0e14', ringR * 1.6, ringR * 6.2]} />

      <CameraRig />
      <OrbitControlsProxy />
      <EmphasisPenController />

      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, -0.05, 0]} raycast={noHit}>
        <circleGeometry args={[ringR * 1.08, 64]} />
        <meshBasicMaterial
          color="#0e141c"
          transparent
          opacity={0.55}
          depthWrite={false}
        />
      </mesh>

      {visiblePages.map((page) => {
        const role =
          page.strandIndex === currentStrand
            ? 'current'
            : page.strandIndex === companionStrand
              ? 'companion'
              : 'background'
        const home = pageHomePosition(page.strandIndex, ringTotal)
        return (
          <PageMesh
            key={`${page.imageUrl ?? 'txt'}-${page.strandIndex}-e${settlementSphereEpoch}`}
            page={page}
            homePosition={home}
            role={role}
            connections={connections}
            currentConnectionId={currentConnectionId}
            onSelectConnection={selectConnection}
            onSwoopToPage={swoopToPage}
          />
        )
      })}

      <Suspense fallback={null}>
        <OcrComparePlane />
      </Suspense>
      <BeamLayer
        pages={pages}
        connections={connections}
        currentStrand={currentStrand}
        companionStrand={companionStrand}
        currentConnectionId={currentConnectionId}
      />
      <EmphasisBeamLayer />
      <Suspense fallback={null}>
        <RelationPasteLayer />
        <KeyPanelLayer />
      </Suspense>
    </Canvas>
  )
}

